package com.accessaudit.service;
import com.accessaudit.model.*; import com.accessaudit.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.*;
@Service
public class AccessService {
 private final AccessRequestRepository requests; private final AuditEventRepository audit; private final ManagedSystemRepository systems; private final AccessProfileRepository profiles; private final AccessGrantRepository grants; private final DirectoryUserRepository directoryUsers;
 public AccessService(AccessRequestRepository requests,AuditEventRepository audit,ManagedSystemRepository systems,AccessProfileRepository profiles,AccessGrantRepository grants,DirectoryUserRepository directoryUsers){this.requests=requests;this.audit=audit;this.systems=systems;this.profiles=profiles;this.grants=grants;this.directoryUsers=directoryUsers;}
 public List<AccessRequest> all(){return requests.findAllByOrderByCreatedAtDesc();}
 public List<AccessRequest> allForEmail(String email){return all().stream().filter(r->r.getEmail().equalsIgnoreCase(email)).toList();}
 public List<AccessGrant> allAccesses(){return grants.findAllByOrderByGrantedAtDesc();}
 public List<AccessGrant> accessesForEmail(String email){return allAccesses().stream().filter(g->g.getEmail().equalsIgnoreCase(email)).toList();}
 public List<AuditEvent> audit(){return audit.findTop200ByOrderByOccurredAtDesc();}
 public List<AuditEvent> auditFor(Long id){return audit.findByRequestIdOrderByOccurredAtDesc(id);}
 public boolean requestBelongsToEmail(Long id,String email){return requests.findById(id).map(r->r.getEmail().equalsIgnoreCase(email)).orElse(false);}
 public List<AuditEvent> auditForEmail(String email){Set<Long> requestIds=new HashSet<>();allForEmail(email).forEach(r->requestIds.add(r.getId()));Set<Long> grantIds=new HashSet<>();accessesForEmail(email).forEach(g->grantIds.add(g.getId()));return audit().stream().filter(e->e.getRequestId()!=null&&e.getRequestId()>0&&requestIds.contains(e.getRequestId())||"ACCESS".equals(e.getEntityType())&&e.getEntityId()!=null&&grantIds.contains(e.getEntityId())).toList();}
 public List<AccessGrant> reviews(){return grants.findByStatusAndReviewDueAtBeforeOrderByReviewDueAtAsc("ACTIVE",Instant.now());}
 public List<AccessGrant> reviewsForEmail(String email){return reviews().stream().filter(g->g.getEmail().equalsIgnoreCase(email)).toList();}
 public Map<String,Object> dashboardForEmail(String email){List<AccessRequest> own=allForEmail(email);long pending=own.stream().filter(r->"PENDING".equals(r.getStatus())).count();long approved=own.stream().filter(r->"APPROVED".equals(r.getStatus())).count();long rejected=own.stream().filter(r->"REJECTED".equals(r.getStatus())).count();long revoked=own.stream().filter(r->"REVOKED".equals(r.getStatus())).count();Map<String,Object> m=new LinkedHashMap<>();m.put("total",own.size());m.put("pending",pending);m.put("approved",approved);m.put("activeAccesses",accessesForEmail(email).stream().filter(g->"ACTIVE".equals(g.getStatus())).count());m.put("rejected",rejected);m.put("revoked",revoked);m.put("reviewAlerts",reviewsForEmail(email).size());m.put("recent",own.stream().limit(8).toList());return m;}
 public Map<String,Object> dashboard(){Map<String,Object> m=new LinkedHashMap<>();m.put("total",requests.count());m.put("pending",requests.countByStatus("PENDING"));m.put("approved",requests.countByStatus("APPROVED"));m.put("activeAccesses",grants.countByStatus("ACTIVE"));m.put("rejected",requests.countByStatus("REJECTED"));m.put("revoked",requests.countByStatus("REVOKED"));m.put("reviewAlerts",reviews().size());m.put("recent",requests.findAllByOrderByCreatedAtDesc().stream().limit(8).toList());return m;}
 @Transactional public AccessRequest create(Map<String,Object> body){
  AccessRequest r=new AccessRequest();String requestedEmail=required(body,"email");DirectoryUser directoryUser=directoryUsers.findAllByOrderByFullNameAsc().stream().filter(u->u.isActive()&&u.getEmail().equalsIgnoreCase(requestedEmail)).findFirst().orElseThrow(()->new IllegalArgumentException("Selecione um usuário ativo do diretório; o e-mail precisa corresponder ao cadastro."));r.setRequester(directoryUser.getFullName());r.setEmail(directoryUser.getEmail());r.setSystemName(required(body,"systemName"));r.setAccessRole(required(body,"accessRole"));r.setJustification(required(body,"justification"));
  String type=String.valueOf(body.getOrDefault("requestType","GRANT")).toUpperCase(Locale.ROOT);if(!Set.of("GRANT","CHANGE","REVOKE").contains(type))throw new IllegalArgumentException("Tipo deve ser GRANT, CHANGE ou REVOKE.");r.setRequestType(type);
  ManagedSystem system=systems.findAllByOrderByNameAsc().stream().filter(s->s.isActive()&&s.getName().equals(r.getSystemName())).findFirst().orElseThrow(()->new IllegalArgumentException("Selecione um sistema ativo do catálogo."));
  profiles.findAllByOrderBySystemNameAscNameAsc().stream().filter(p->p.isActive()&&p.getName().equals(r.getAccessRole())&&p.getSystemName().equals(system.getName())).findFirst().orElseThrow(()->new IllegalArgumentException("Selecione um perfil ativo associado ao sistema escolhido."));
  if("CHANGE".equals(type)){r.setCurrentAccessRole(required(body,"currentAccessRole"));boolean currentExists=profiles.findAllByOrderBySystemNameAscNameAsc().stream().anyMatch(p->p.isActive()&&p.getName().equals(r.getCurrentAccessRole())&&p.getSystemName().equals(system.getName()));if(!currentExists)throw new IllegalArgumentException("O perfil atual precisa existir no sistema selecionado.");if(r.getCurrentAccessRole().equalsIgnoreCase(r.getAccessRole()))throw new IllegalArgumentException("O perfil atual e o novo perfil precisam ser diferentes.");if(grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getCurrentAccessRole(),"ACTIVE").isEmpty())throw new IllegalArgumentException("Não existe um acesso ativo com o perfil atual informado.");if(grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getAccessRole(),"ACTIVE").isPresent())throw new IllegalArgumentException("O colaborador já possui o perfil de destino ativo.");}
  if("REVOKE".equals(type)&&grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getAccessRole(),"ACTIVE").isEmpty())throw new IllegalArgumentException("Não existe acesso ativo correspondente para revogar.");
  if("GRANT".equals(type)&&grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getAccessRole(),"ACTIVE").isPresent())throw new IllegalArgumentException("Este colaborador já possui esse perfil ativo no sistema.");
  r.setStatus("PENDING");r=requests.save(r);audit.save(new AuditEvent(r.getId(),"REQUEST_CREATED",body.get("actor")==null?r.getRequester():String.valueOf(body.get("actor")),"Solicitação de "+type+" para "+r.getSystemName()+" / "+r.getAccessRole()));return r;
 }
 @Transactional public AccessRequest decide(Long id,Map<String,Object> body){
  AccessRequest r=get(id);String decision=required(body,"decision").toUpperCase(Locale.ROOT);if(!Set.of("APPROVED","REJECTED").contains(decision))throw new IllegalArgumentException("Decisão deve ser APPROVED ou REJECTED.");if(!"PENDING".equals(r.getStatus()))throw new IllegalStateException("Somente solicitações pendentes podem ser decididas.");String reviewer=required(body,"reviewer");String note=body.get("note")==null?"":String.valueOf(body.get("note")).trim();if("REJECTED".equals(decision)&&note.length()<5)throw new IllegalArgumentException("Informe uma justificativa de pelo menos 5 caracteres para rejeitar.");
  if("APPROVED".equals(decision))applyApproval(r,id,reviewer,note);
  String finalStatus=("APPROVED".equals(decision)&&"REVOKE".equals(r.getRequestType()))?"REVOKED":decision;r.setStatus(finalStatus);r.setReviewer(reviewer);r.setReviewNote(note);r.setDecidedAt(Instant.now());if("APPROVED".equals(finalStatus))r.setReviewDueAt(Instant.now().plus(90,ChronoUnit.DAYS));r=requests.save(r);String action="REVOKED".equals(finalStatus)?"ACCESS_REVOKED":decision;audit.save(new AuditEvent(id,action,reviewer,("CHANGE".equals(r.getRequestType())?"Perfil alterado de "+r.getCurrentAccessRole()+" para "+r.getAccessRole()+". ":"")+note));return r;
 }
 private void applyApproval(AccessRequest r,Long requestId,String actor,String note){Instant nextReview=Instant.now().plus(90,ChronoUnit.DAYS);
  if("GRANT".equals(r.getRequestType())){if(grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getAccessRole(),"ACTIVE").isPresent())throw new IllegalStateException("O acesso já foi concedido em outra solicitação.");AccessGrant g=new AccessGrant(r.getRequester(),r.getEmail(),r.getSystemName(),r.getAccessRole(),requestId);g.setReviewDueAt(nextReview);grants.save(g);audit.save(new AuditEvent("ACCESS",g.getId(),"ACCESS_GRANTED",actor,"Acesso concedido: "+g.getSystemName()+" / "+g.getProfileName()+". "+note));}
  else if("CHANGE".equals(r.getRequestType())){if(grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getAccessRole(),"ACTIVE").isPresent())throw new IllegalStateException("O perfil de destino já está ativo para este colaborador.");AccessGrant g=grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getCurrentAccessRole(),"ACTIVE").orElseThrow(()->new IllegalStateException("O acesso atual não está ativo; não foi possível alterar o perfil."));g.setProfileName(r.getAccessRole());g.setSourceRequestId(requestId);g.setReviewDueAt(nextReview);grants.save(g);audit.save(new AuditEvent("ACCESS",g.getId(),"ACCESS_PROFILE_CHANGED",actor,"Perfil alterado de "+r.getCurrentAccessRole()+" para "+r.getAccessRole()+". "+note));}
  else if("REVOKE".equals(r.getRequestType())){AccessGrant g=grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getAccessRole(),"ACTIVE").orElseThrow(()->new IllegalStateException("O acesso não está mais ativo; não foi possível revogar."));g.setStatus("REVOKED");grants.save(g);audit.save(new AuditEvent("ACCESS",g.getId(),"ACCESS_REVOKED",actor,"Acesso revogado: "+g.getSystemName()+" / "+g.getProfileName()+". "+note));}
 }
 @Transactional public AccessRequest revoke(Long id,Map<String,Object> body){AccessRequest r=get(id);if(!"APPROVED".equals(r.getStatus()))throw new IllegalStateException("Somente solicitações aprovadas podem ser revogadas diretamente.");String actor=required(body,"actor"),note=required(body,"note");AccessGrant g=grants.findFirstByEmailIgnoreCaseAndSystemNameAndProfileNameAndStatus(r.getEmail(),r.getSystemName(),r.getAccessRole(),"ACTIVE").orElseThrow(()->new IllegalStateException("Não existe acesso ativo correspondente para revogar."));g.setStatus("REVOKED");grants.save(g);r.setStatus("REVOKED");r.setReviewer(actor);r.setReviewNote(note);r.setDecidedAt(Instant.now());r=requests.save(r);audit.save(new AuditEvent(id,"ACCESS_REVOKED",actor,note));audit.save(new AuditEvent("ACCESS",g.getId(),"ACCESS_REVOKED",actor,note));return r;}
 @Transactional public AccessGrant reviewAccess(Long id,Map<String,Object> body){AccessGrant g=grants.findById(id).orElseThrow(()->new NoSuchElementException("Acesso não encontrado."));if(!"ACTIVE".equals(g.getStatus()))throw new IllegalStateException("Somente acessos ativos podem ser revisados.");String actor=required(body,"actor"),note=required(body,"note");g.setReviewDueAt(Instant.now().plus(90,ChronoUnit.DAYS));g=grants.save(g);audit.save(new AuditEvent("ACCESS",g.getId(),"ACCESS_REVIEWED",actor,"Revisão concluída. Próxima revisão em 90 dias. "+note));return g;}
 private AccessRequest get(Long id){return requests.findById(id).orElseThrow(()->new NoSuchElementException("Solicitação não encontrada: "+id));}
 private String required(Map<String,?> b,String key){Object raw=b.get(key);String v=raw==null?"":String.valueOf(raw).trim();if(v.isEmpty())throw new IllegalArgumentException("Campo obrigatório: "+key);return v;}
}
